var w7=function(){var a=$g(ug),b=$g(ug),c=$g(ug),d=$g(ug),e=Od(ug,By,al.v?al.v():al.call(null));return new ml(Pd.h("synthigy.log.cockpit.ui","lens-view"),function(f){return ho.g(R2(f))},e,a,b,c,d)}();w7.B(null,zl,function(a){return new R(null,3,5,S,[eja,Zza(a),new R(null,3,5,S,[Ffa,eAa(a),aAa(a)],null)],null)});w7.B(null,wv,function(a){return gza(a)});w7.B(null,YL,function(a){return sza(a)});w7.B(null,ry,function(a){return Pya(a)});w7.B(null,gN,function(){return Nza()});
function hAa(a,b){return new R(null,6,5,S,[Cba,k2(null),l(bx.g(a))?null:M8(),Xza(M.j(a,mq,b)),l(Hm.g(b))?gAa(b):null,w7.g(b)],null)};var a2=new CSSStyleSheet;a2.replaceSync("/* Synthigy Log Cockpit — Phase 1 skeleton.\n * Variable conventions mirror data/console/console.css:\n *   --sy-*         Synthigy semantic colors (text, background, accents)\n *   --modeling-*   Modeler chrome (overlays, handles)\n * Never hardcode colors — always var() with a sensible fallback.\n *\n * Class prefix: .lc-  (log cockpit).\n *\n * After editing this file, ALSO save component.cljs to re-run the\n * defstyles macro — bare .css edits are not seen by shadow-cljs.\n */\n\n/* ── Host ───────────────────────────────────────────────────────────────────── */\n:host {\n  display: none;\n  position: fixed;\n  inset: 0;\n  z-index: 9998;\n  font-family: 'Inter', system-ui, -apple-system, sans-serif;\n  font-size: 13px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n:host([open]) { display: block; }\n\n*, *::before, *::after { box-sizing: border-box; }\n\n/* ── Root layout ────────────────────────────────────────────────────────────── */\n.lc-root {\n  position: relative;           /* containing block for the starfield */\n  isolation: isolate;           /* keeps z-index:-1 starfield above .lc-root bg */\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n  height: 100%;\n  background: var(--sy-bg-app, #161616);\n  color: var(--sy-text-primary, #d4d4d4);\n}\n\n/* ── Toolbar ────────────────────────────────────────────────────────────────── */\n.lc-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 0 12px;\n  height: 38px;\n  background: var(--sy-bg-surface, #1e1e1e);\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  flex-shrink: 0;\n}\n.lc-toolbar-brand {\n  display: flex;\n  align-items: center;\n  margin-top: 10px;\n  margin-left: -10px;\n  pointer-events: none;\n}\n.lc-toolbar-brand svg { height: 28px; width: auto; display: block; }\n.lc-toolbar-title {\n  margin-top: 4px;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--sy-text-muted, #666);\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n}\n.lc-toolbar-spacer { flex: 1; }\n\n.lc-toolbar-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  background: none;\n  border: 1px solid transparent;\n  padding: 3px 8px;\n  font-size: 11px;\n  color: var(--sy-text-muted, #666);\n  border-radius: 3px;\n  cursor: pointer;\n  transition: background .12s, color .12s, border-color .12s;\n}\n.lc-toolbar-btn:hover {\n  background: var(--sy-hover-overlay, rgba(255,255,255,.05));\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lc-toolbar-btn:disabled { opacity: 0.5; cursor: wait; }\n.lc-toolbar-btn.live {\n  color: var(--sy-op-sql, #a8adb5);\n  border-color: var(--sy-op-sql, #a8adb5);\n}\n.lc-toolbar-btn.live.paused {\n  color: var(--sy-op-write, #f0f0f0);\n  border-color: var(--sy-op-write, #f0f0f0);\n}\n\n.lc-since-select {\n  appearance: none;\n  -webkit-appearance: none;\n  background: var(--sy-bg-band, #252525);\n  color: var(--sy-text-primary, #d4d4d4);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  padding: 3px 22px 3px 8px;\n  font-size: 11px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  cursor: pointer;\n  /* Inline chevron — no native one when appearance is reset. */\n  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),\n                    linear-gradient(135deg, currentColor 50%, transparent 50%);\n  background-position: calc(100% - 12px) 50%, calc(100% - 8px) 50%;\n  background-size: 4px 4px, 4px 4px;\n  background-repeat: no-repeat;\n}\n\n/* ── Lens tabs (in toolbar) ─────────────────────────────────────────────────── */\n.lc-lens-tabs {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  margin-left: 8px;\n}\n.lc-lens-tab {\n  background: none;\n  border: none;\n  padding: 4px 10px;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sy-text-muted, #666);\n  border-radius: 3px;\n  cursor: pointer;\n  transition: background .12s, color .12s;\n}\n.lc-lens-tab:hover {\n  background: var(--sy-hover-overlay, rgba(255,255,255,.05));\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lc-lens-tab.selected {\n  background: var(--sy-accent-tint, rgba(255, 255, 255,.14));\n  color: var(--sy-accent, #e2e2e2);\n}\n.lc-lens-tab.pro {\n  color: var(--sy-text-faint, #3a3a3a);\n}\n.lc-lens-tab.pro::after {\n  content: \" ★\";\n  color: var(--sy-op-write, #f0f0f0);\n}\n.lc-lens-tab.locked {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* ── Body (form sidebar + main) ─────────────────────────────────────────────── */\n.lc-body {\n  display: flex;\n  flex: 1;\n  overflow: hidden;\n  position: relative;\n}\n\n/* ── Per-lens filter form sidebar ───────────────────────────────────────────── */\n.lc-form-sidebar {\n  flex: 0 0 240px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 14px 14px 12px;\n  border-right: 1px solid var(--sy-border, #2a2a2a);\n  background: var(--sy-bg-surface, #1e1e1e);\n  overflow-y: auto;\n}\n.lc-form-title {\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--sy-text-primary, #d4d4d4);\n  padding-bottom: 2px;\n}\n.lc-form-desc {\n  font-size: 11px;\n  color: var(--sy-text-muted, #666);\n  line-height: 1.4;\n  padding-bottom: 4px;\n  border-bottom: 1px solid var(--sy-border-subtle, rgba(255,255,255,.04));\n}\n.lc-form-fields {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.lc-form-field {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n.lc-form-label {\n  font-size: 10px;\n  color: var(--sy-text-faint, #3a3a3a);\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n}\n.lc-form-input,\n.lc-form-select {\n  width: 100%;\n  padding: 5px 8px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 12px;\n  color: var(--sy-text-primary, #d4d4d4);\n  background: var(--sy-bg-band, #252525);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  outline: none;\n  transition: border-color .12s ease;\n}\n.lc-form-input::placeholder { color: var(--sy-text-faint, #3a3a3a); }\n.lc-form-input:focus,\n.lc-form-select:focus { border-color: var(--sy-accent, #e2e2e2); }\n.lc-form-select {\n  appearance: none;\n  background-image: url(\"data:image/svg+xml,%3Csvg xmlns\x3d'http://www.w3.org/2000/svg' width\x3d'10' height\x3d'6' viewBox\x3d'0 0 10 6'%3E%3Cpath fill\x3d'none' stroke\x3d'%23666' stroke-width\x3d'1.4' stroke-linecap\x3d'round' stroke-linejoin\x3d'round' d\x3d'M1 1l4 4 4-4'/%3E%3C/svg%3E\");\n  background-repeat: no-repeat;\n  background-position: right 8px center;\n  padding-right: 24px;\n}\n.lc-form-clear {\n  align-self: flex-start;\n  margin-top: 4px;\n  padding: 4px 10px;\n  font-size: 11px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  color: var(--sy-text-muted, #666);\n  background: none;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  cursor: pointer;\n  transition: color .12s ease, border-color .12s ease;\n}\n.lc-form-clear:hover {\n  color: var(--sy-op-write, #f0f0f0);\n  border-color: var(--sy-op-write, #f0f0f0);\n}\n\n/* ── Stats bar — floating badges in the bottom-right of the stream ──────────── */\n.lc-stats {\n  position: absolute;\n  right: 16px;\n  bottom: 16px;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 8px;\n  background: var(--sy-bg-surface, rgba(255,255,255,.95));\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 18px;\n  box-shadow: 0 2px 8px rgba(0,0,0,.08);\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 11px;\n  backdrop-filter: blur(8px);\n}\n.lc-stat {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 4px;\n  padding: 2px 8px;\n  border-radius: 10px;\n  background: var(--sy-bg-band, #252525);\n  border: 1px solid var(--sy-border-subtle, rgba(0,0,0,.08));\n  color: var(--sy-text-muted, #666);\n  cursor: pointer;\n  transition: background .12s, color .12s, border-color .12s;\n}\n.lc-stat:hover {\n  background: var(--sy-hover-overlay, rgba(0,0,0,.04));\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lc-stat-count {\n  font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lc-stat-unit  { color: var(--sy-text-muted, #666); }\n\n.lc-stat.lc-stat-rows         { border-color: var(--sy-accent, #e2e2e2); }\n.lc-stat.lc-stat-rows .lc-stat-count { color: var(--sy-accent, #e2e2e2); }\n\n.lc-stat-lvl.lvl-info  .lc-stat-count { color: var(--sy-accent, #e2e2e2); }\n.lc-stat-lvl.lvl-warn  .lc-stat-count { color: var(--sy-op-write, #f0f0f0); }\n.lc-stat-lvl.lvl-error .lc-stat-count { color: var(--sy-error, #f7768e); }\n.lc-stat-lvl.lvl-fatal .lc-stat-count { color: var(--sy-error, #f7768e); }\n.lc-stat-lvl.lvl-debug .lc-stat-count { color: var(--sy-text-muted, #666); }\n.lc-stat-lvl.lvl-trace .lc-stat-count { color: var(--sy-text-faint, #3a3a3a); }\n\n.lc-stat.lc-stat-timing { cursor: default; }\n.lc-stat.lc-stat-timing:hover { background: var(--sy-bg-band, #252525); }\n\n/* ── Settings drawer (toolbar gear opens this overlay) ─────────────────────── */\n.lc-settings-drawer {\n  position: absolute;\n  top: 0;\n  right: 0;\n  z-index: 20;\n  width: 360px;\n  max-height: calc(100% - 12px);\n  padding: 14px 16px 16px;\n  background: var(--sy-bg-surface, #1e1e1e);\n  border-left: 1px solid var(--sy-border, #2a2a2a);\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  border-bottom-left-radius: 6px;\n  box-shadow: -4px 8px 24px rgba(0,0,0,.32);\n  overflow-y: auto;\n  font-size: 12px;\n}\n.lc-toolbar-btn.active {\n  background: var(--sy-accent-tint, rgba(255, 255, 255,.14));\n  color: var(--sy-accent, #e2e2e2);\n}\n\n/* ── Settings panel (log-level control — content of the drawer) ────────────── */\n.lc-settings-section { margin-bottom: 16px; }\n.lc-settings-title {\n  font-size: 10px;\n  font-weight: 600;\n  color: var(--sy-text-muted, #666);\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  margin-bottom: 6px;\n}\n.lc-settings-select {\n  appearance: none;\n  -webkit-appearance: none;\n  width: 100%;\n  background: var(--sy-bg-band, #252525);\n  color: var(--sy-text-primary, #d4d4d4);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  padding: 4px 22px 4px 8px;\n  font-size: 12px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  cursor: pointer;\n  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),\n                    linear-gradient(135deg, currentColor 50%, transparent 50%);\n  background-position: calc(100% - 12px) 50%, calc(100% - 8px) 50%;\n  background-size: 4px 4px, 4px 4px;\n  background-repeat: no-repeat;\n}\n\n/* ── Add-override row ──────────────────────────────────────────────────────── */\n.lc-ns-add {\n  display: flex;\n  gap: 4px;\n  align-items: center;\n}\n.lc-ns-input {\n  flex: 1;\n  min-width: 0;\n  background: var(--sy-bg-band, #252525);\n  color: var(--sy-text-primary, #d4d4d4);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  padding: 4px 6px;\n  font-size: 11px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n}\n.lc-ns-input:focus {\n  outline: none;\n  border-color: var(--sy-accent, #e2e2e2);\n}\n.lc-ns-level-select {\n  appearance: none;\n  -webkit-appearance: none;\n  background: var(--sy-bg-band, #252525);\n  color: var(--sy-text-primary, #d4d4d4);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  padding: 4px 20px 4px 6px;\n  font-size: 11px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  cursor: pointer;\n  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),\n                    linear-gradient(135deg, currentColor 50%, transparent 50%);\n  background-position: calc(100% - 10px) 50%, calc(100% - 6px) 50%;\n  background-size: 4px 4px, 4px 4px;\n  background-repeat: no-repeat;\n}\n.lc-ns-add-btn {\n  background: var(--sy-bg-band, #252525);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-primary, #d4d4d4);\n  padding: 4px 10px;\n  font-size: 11px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  cursor: pointer;\n}\n.lc-ns-add-btn:hover:not(:disabled) {\n  border-color: var(--sy-accent, #e2e2e2);\n  color: var(--sy-accent, #e2e2e2);\n}\n.lc-ns-add-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.lc-settings-hint {\n  font-size: 10px;\n  color: var(--sy-text-muted, #666);\n  margin-top: 4px;\n  line-height: 1.4;\n}\n.lc-settings-hint code {\n  background: var(--sy-bg-band, #252525);\n  padding: 0 4px;\n  border-radius: 2px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  color: var(--sy-text-primary, #d4d4d4);\n}\n\n.lc-ns-list {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n.lc-ns-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 3px 6px;\n  background: var(--sy-bg-band, #252525);\n  border: 1px solid var(--sy-border-subtle, rgba(0,0,0,.06));\n  border-radius: 3px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 11px;\n}\n.lc-ns-pattern {\n  flex: 1;\n  color: var(--sy-text-primary, #d4d4d4);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.lc-ns-level {\n  color: var(--sy-accent, #e2e2e2);\n  font-weight: 500;\n}\n.lc-ns-x {\n  background: none;\n  border: none;\n  color: var(--sy-text-muted, #666);\n  cursor: pointer;\n  padding: 0 4px;\n}\n.lc-ns-x:hover { color: var(--sy-op-write, #f0f0f0); }\n\n.lc-settings-source {\n  font-size: 11px;\n  color: var(--sy-text-muted, #666);\n  margin-bottom: 6px;\n}\n.lc-settings-source-tag {\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  color: var(--sy-accent, #e2e2e2);\n}\n.lc-settings-revert {\n  background: none;\n  border: 1px dashed var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-muted, #666);\n  padding: 4px 8px;\n  font-size: 11px;\n  cursor: pointer;\n  width: 100%;\n}\n.lc-settings-revert:hover {\n  color: var(--sy-op-write, #f0f0f0);\n  border-color: var(--sy-op-write, #f0f0f0);\n}\n.lc-settings-error {\n  font-size: 11px;\n  color: var(--sy-error, #f7768e);\n  padding: 6px 8px;\n  border: 1px solid var(--sy-error, #f7768e);\n  border-radius: 3px;\n  margin-top: 8px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n}\n.lc-main {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  position: relative;   /* anchor for floating .lc-stats overlay */\n}\n\n/* ── Stream ─────────────────────────────────────────────────────────────────── */\n.lc-stream {\n  flex: 1;\n  overflow-y: auto;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 12px;\n}\n.lc-row {\n  display: grid;\n  grid-template-columns: 72px 56px 240px 1fr;\n  gap: 12px;\n  padding: 8px 14px;\n  align-items: flex-start;\n  border-bottom: 1px solid var(--sy-border-subtle, rgba(255,255,255,.03));\n  cursor: pointer;\n}\n.lc-row:hover { background: var(--sy-hover-overlay, rgba(255,255,255,.04)); }\n.lc-row.selected { background: var(--sy-accent-tint, rgba(255, 255, 255,.08)); }\n\n.lc-row-ts {\n  color: var(--sy-text-muted, #666);\n  font-variant-numeric: tabular-nums;\n  padding-top: 1px;\n}\n.lc-row-id {\n  color: var(--sy-text-muted, #666);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  padding-top: 1px;\n}\n.lc-row-msg {\n  color: var(--sy-text-primary, #d4d4d4);\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 12px;\n  min-width: 0;\n}\n.lc-row-msg-text {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding-top: 1px;\n  word-break: break-word;\n  white-space: normal;\n  line-height: 1.45;\n}\n.lc-row-actions {\n  flex: 0 0 auto;\n  display: flex;\n  gap: 6px;\n}\n\n/* Right-aligned action buttons on each row. Click → filters the lens\n   form by the row's user_xid / request_id. Distinct from a \"pill\" — these\n   read as buttons: icon + value, accent on hover. */\n.lc-row-action {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 20px;\n  padding: 0 8px;\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 11px;\n  color: var(--sy-text-primary, #d4d4d4);\n  background: var(--sy-bg-band, #252525);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 4px;\n  cursor: pointer;\n  line-height: 1;\n  transition: background .12s ease, border-color .12s ease, color .12s ease;\n}\n.lc-row-action:hover {\n  background: var(--sy-accent, #e2e2e2);\n  border-color: var(--sy-accent, #e2e2e2);\n  color: var(--sy-bg-app, #161616);\n}\n.lc-row-action-icon { opacity: 0.7; }\n.lc-row-action:hover .lc-row-action-icon { opacity: 1; }\n.lc-row-action-value {\n  font-variant-numeric: tabular-nums;\n  margin-top: 3px;\n}\n\n.lc-row-lvl                          { font-weight: 600; text-transform: uppercase; font-size: 10px; }\n.lc-row-lvl.lvl-trace                { color: var(--sy-text-faint, #3a3a3a); }\n.lc-row-lvl.lvl-debug                { color: var(--sy-text-muted, #666); }\n.lc-row-lvl.lvl-info                 { color: var(--sy-accent, #e2e2e2); }\n.lc-row-lvl.lvl-warn                 { color: var(--sy-op-write, #f0f0f0); }\n.lc-row-lvl.lvl-error                { color: var(--sy-error, #f7768e); }\n.lc-row-lvl.lvl-fatal                { color: var(--sy-error, #f7768e); background: rgba(247,118,142,.1); }\n\n.lc-row-expanded {\n  padding: 8px 12px 12px 102px;\n  color: var(--sy-text-muted, #666);\n  font-size: 11px;\n  background: var(--sy-bg-surface, #1e1e1e);\n}\n.lc-row-expanded .k {\n  color: var(--sy-text-muted, #666);\n  white-space: pre;\n}\n.lc-row-expanded .v {\n  color: var(--sy-text-primary, #d4d4d4);\n  word-break: break-word;\n  white-space: pre-wrap;\n}\n.lc-row-expanded .v.pivot {\n  cursor: pointer;\n  border-bottom: 1px dashed transparent;\n  transition: border-color .12s ease, color .12s ease;\n}\n.lc-row-expanded .v.pivot:hover {\n  color: var(--sy-accent, #e2e2e2);\n  border-bottom-color: var(--sy-accent, #e2e2e2);\n}\n.lc-row-expanded .lc-kv-section {\n  margin-top: 6px;\n}\n.lc-row-expanded .lc-kv-section .k {\n  color: var(--sy-text-primary, #d4d4d4);\n  text-transform: uppercase;\n  font-size: 10px;\n  letter-spacing: 0.05em;\n}\n.lc-row-expanded .lc-error-trace {\n  margin: 6px 0 0;\n  padding: 8px 10px;\n  background: var(--sy-bg-band, rgba(0,0,0,.18));\n  color: var(--sy-error, #f7768e);\n  font-family: 'JetBrains Mono', 'Fira Code', monospace;\n  font-size: 10.5px;\n  line-height: 1.5;\n  white-space: pre;\n  overflow-x: auto;\n  border-left: 2px solid var(--sy-error, #f7768e);\n  border-radius: 2px;\n}\n.lc-row-kv {\n  color: var(--sy-text-muted, #666);\n  font-size: 11px;\n}\n.lc-kv {\n  display: grid;\n  grid-template-columns: 110px minmax(0, 1fr);\n  gap: 8px;\n  align-items: baseline;\n  padding: 1px 0;\n}\n\n.lc-empty-hint {\n  font-size: 11px;\n  color: var(--sy-text-faint, #3a3a3a);\n}\n\n/* ── Empty + loading states ─────────────────────────────────────────────────── */\n.lc-empty,\n.lc-loading,\n.lc-error {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  color: var(--sy-text-muted, #666);\n  font-size: 12px;\n  gap: 8px;\n}\n.lc-error { color: var(--sy-error, #f7768e); }\n\n/* ── Pro overlay (for locked lenses) ────────────────────────────────────────── */\n.lc-pro-overlay {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(22, 22, 22, 0.92);\n  z-index: 10;\n}\n.lc-pro-card {\n  max-width: 420px;\n  padding: 24px;\n  border: 1px solid var(--sy-op-write, #f0f0f0);\n  border-radius: 6px;\n  text-align: center;\n}\n\n/* ═══════════════════════════════════════════════════════════════════════════\n * SQL lens — class prefix .lens-*. Owned by lens/sql.cljs, dispatched from\n * ui/lens-view :sql. Drops the generic form-sidebar + stream in favour of\n * a focus selector + drillable table.\n * ═════════════════════════════════════════════════════════════════════════ */\n\n.lens-lens {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  min-height: 0;\n}\n\n/* ── Control bar (focus selector + debug toggle) ─────────────────────────── */\n.lens-control-bar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  background: var(--sy-bg-surface, #1e1e1e);\n  flex-shrink: 0;\n}\n.lens-control-spacer { flex: 1; }\n\n/* ── Pickers (Entity / User / Operation / Request) ───────────────────────── */\n.lens-pickers {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.lens-picker { position: relative; }\n.lens-picker-inline { display: inline-flex; align-items: center; }\n\n.lens-picker-trigger {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 26px;\n  padding: 0 10px;\n  font-size: 12px;\n  background: transparent;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-muted, #888);\n  cursor: pointer;\n  transition: color 80ms, background 80ms, border-color 80ms;\n}\n.lens-picker-trigger:hover {\n  color: var(--sy-text-primary, #d4d4d4);\n  border-color: var(--sy-border-strong, #3a3a3a);\n}\n.lens-picker-trigger.open,\n.lens-picker-trigger.has-values {\n  color: var(--sy-accent, #e2e2e2);\n  border-color: var(--sy-accent, #e2e2e2);\n  background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 10%, transparent);\n}\n.lens-picker-label { letter-spacing: 0.01em; }\n.lens-picker-count {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 18px;\n  height: 16px;\n  padding: 0 4px;\n  font-size: 10.5px;\n  font-weight: 600;\n  color: var(--sy-bg-app, #161616);\n  background: var(--sy-accent, #e2e2e2);\n  border-radius: 8px;\n}\n.lens-picker-caret {\n  display: inline-flex;\n  align-items: center;\n  transform: rotate(90deg);\n  transition: transform 100ms;\n}\n.lens-picker-trigger.open .lens-picker-caret { transform: rotate(-90deg); }\n\n.lens-picker-text {\n  height: 26px;\n  width: 160px;\n  padding: 0 10px;\n  font-size: 12px;\n  background: transparent;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-primary, #d4d4d4);\n  font-family: ui-monospace, monospace;\n}\n.lens-picker-text:focus {\n  outline: none;\n  border-color: var(--sy-accent, #e2e2e2);\n}\n.lens-picker-text::placeholder { color: var(--sy-text-faint, #3a3a3a); }\n\n.lens-picker-panel {\n  position: absolute;\n  top: calc(100% + 4px);\n  left: 0;\n  z-index: 50;\n  min-width: 240px;\n  max-width: 360px;\n  background: var(--sy-bg-surface, #1e1e1e);\n  border: 1px solid var(--sy-border-strong, #3a3a3a);\n  border-radius: 4px;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  max-height: 380px;\n}\n.lens-picker-panel-user { min-width: 280px; }\n.lens-picker-search {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 10px 6px 10px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n}\n.lens-picker-search-input {\n  flex: 1;\n  height: 24px;\n  padding: 0 8px;\n  font-size: 12px;\n  background: var(--sy-bg-app, #161616);\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lens-picker-search-input:focus {\n  outline: none;\n  border-color: var(--sy-accent, #e2e2e2);\n}\n.lens-picker-spin {\n  color: var(--sy-text-faint, #3a3a3a);\n  font-size: 11px;\n}\n.lens-picker-panel-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 4px 0;\n}\n.lens-picker-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 10px;\n  cursor: pointer;\n  user-select: none;\n}\n.lens-picker-row:hover { background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 10%, transparent); }\n.lens-picker-cb { cursor: pointer; }\n.lens-picker-row-label {\n  font-size: 12px;\n  color: var(--sy-text-primary, #d4d4d4);\n  display: inline-flex;\n  flex-direction: column;\n  min-width: 0;\n}\n.lens-picker-row-sub {\n  font-family: ui-monospace, monospace;\n  font-size: 10.5px;\n  color: var(--sy-text-faint, #3a3a3a);\n}\n.lens-picker-hint {\n  padding: 8px 10px;\n  font-size: 11px;\n  color: var(--sy-text-faint, #3a3a3a);\n}\n.lens-picker-clear {\n  margin: 4px 8px 8px 8px;\n  height: 22px;\n  padding: 0 10px;\n  font-size: 11px;\n  background: transparent;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-muted, #888);\n  cursor: pointer;\n  align-self: flex-end;\n}\n.lens-picker-clear:hover { color: var(--sy-error, #f7768e); border-color: var(--sy-error, #f7768e); }\n\n.lens-debug-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 26px;\n  padding: 0 10px;\n  font-size: 11px;\n  background: transparent;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-muted, #888);\n  cursor: pointer;\n  transition: color 80ms, background 80ms, border-color 80ms;\n}\n.lens-debug-toggle .lens-debug-dot {\n  width: 7px; height: 7px;\n  border-radius: 50%;\n  background: var(--sy-text-faint, #3a3a3a);\n  transition: background 80ms;\n}\n.lens-debug-toggle:hover {\n  color: var(--sy-text-primary, #d4d4d4);\n  border-color: var(--sy-border-strong, #3a3a3a);\n}\n.lens-debug-toggle.on {\n  color: var(--sy-op-write, #f0f0f0);\n  border-color: var(--sy-op-write, #f0f0f0);\n  background: color-mix(in srgb, var(--sy-op-write, #f0f0f0) 14%, transparent);\n}\n.lens-debug-toggle.on .lens-debug-dot {\n  background: var(--sy-op-write, #f0f0f0);\n  box-shadow: 0 0 6px var(--sy-op-write, #f0f0f0);\n}\n\n/* ── Debug warning banner ────────────────────────────────────────────────── */\n.lens-debug-banner {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 12px;\n  font-size: 12px;\n  color: var(--sy-op-write, #f0f0f0);\n  background: color-mix(in srgb, var(--sy-op-write, #f0f0f0) 10%, transparent);\n  border-bottom: 1px solid color-mix(in srgb, var(--sy-op-write, #f0f0f0) 30%, transparent);\n  flex-shrink: 0;\n}\n\n/* ── Crumb bar (multi-value per axis) ────────────────────────────────────── */\n.lens-crumbs {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 6px 10px;\n  padding: 6px 12px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  background: var(--sy-bg-app, #161616);\n  flex-shrink: 0;\n  min-height: 36px;\n}\n.lens-crumb-clear {\n  height: 22px;\n  padding: 0 10px;\n  font-size: 11px;\n  background: transparent;\n  border: 1px solid var(--sy-border, #2a2a2a);\n  border-radius: 3px;\n  color: var(--sy-text-muted, #888);\n  cursor: pointer;\n}\n.lens-crumb-clear:disabled { opacity: 0.4; cursor: default; }\n.lens-crumb-clear:hover:not(:disabled) {\n  color: var(--sy-error, #f7768e);\n  border-color: var(--sy-error, #f7768e);\n}\n.lens-crumb-group {\n  display: inline-flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 4px;\n}\n.lens-crumb-axis {\n  font-size: 10.5px;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--sy-text-faint, #3a3a3a);\n  margin-right: 2px;\n}\n.lens-crumb-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  height: 22px;\n  padding: 0 4px 0 8px;\n  font-size: 12px;\n  border-radius: 3px;\n  background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 12%, transparent);\n  color: var(--sy-accent, #e2e2e2);\n  border: 1px solid color-mix(in srgb, var(--sy-accent, #e2e2e2) 40%, transparent);\n}\n.lens-crumb-label { font-weight: 500; }\n.lens-crumb-x {\n  background: transparent;\n  border: 0;\n  padding: 0 4px;\n  font-size: 14px;\n  line-height: 1;\n  color: currentColor;\n  cursor: pointer;\n  opacity: 0.7;\n}\n.lens-crumb-x:hover { opacity: 1; }\n\n/* ── Table ───────────────────────────────────────────────────────────────── */\n.lens-table-wrap {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n}\n.lens-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n}\n.lens-th {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  text-align: left;\n  padding: 6px 8px;\n  font-weight: 500;\n  font-size: 10.5px;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--sy-text-faint, #3a3a3a);\n  background: var(--sy-bg-surface, #1e1e1e);\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  white-space: nowrap;\n}\n.lens-row {\n  cursor: pointer;\n  border-bottom: 1px solid color-mix(in srgb, var(--sy-border, #2a2a2a) 50%, transparent);\n}\n.lens-row:hover { background: var(--sy-bg-surface, #1e1e1e); }\n.lens-row.selected { background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 8%, transparent); }\n.lens-row.err { background: color-mix(in srgb, var(--sy-error, #f7768e) 8%, transparent); }\n.lens-cell {\n  padding: 4px 8px;\n  vertical-align: middle;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 260px;\n}\n.lens-cell-ts {\n  color: var(--sy-text-muted, #888);\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n}\n/* System lens time column carries a date line above the time (the\n   timeline can land on any day, so the date matters). */\n.lens-cell-ts-dt { line-height: 1.25; white-space: nowrap; }\n.lens-cell-ts-dt .lens-ts-date {\n  display: block; font-size: 10px; color: var(--sy-text-faint, #3a3a3a);\n}\n.lens-cell-ts-dt .lens-ts-time { display: block; }\n.lens-cell-lvl {\n  font-size: 10.5px;\n  text-transform: uppercase;\n  text-align: center;\n  width: 50px;\n}\n.lens-cell-lvl.lvl-trace { color: var(--sy-text-faint, #3a3a3a); }\n.lens-cell-lvl.lvl-debug { color: var(--sy-text-muted, #888); }\n.lens-cell-lvl.lvl-info  { color: var(--sy-info, #9aa0a8); }\n.lens-cell-lvl.lvl-warn  { color: var(--sy-warn, #e0af68); }\n.lens-cell-lvl.lvl-error,\n.lens-cell-lvl.lvl-fatal { color: var(--sy-error, #f7768e); }\n\n.lens-cell-kind { width: 60px; }\n.lens-pill {\n  display: inline-block;\n  padding: 1px 6px;\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n  border-radius: 2px;\n}\n.lens-pill.kind-read {\n  color: var(--sy-info, #9aa0a8);\n  background: color-mix(in srgb, var(--sy-info, #9aa0a8) 14%, transparent);\n}\n.lens-pill.kind-write {\n  color: var(--sy-op-write, #f0f0f0);\n  background: color-mix(in srgb, var(--sy-op-write, #f0f0f0) 14%, transparent);\n}\n\n.lens-cell-op,\n.lens-cell-entity,\n.lens-cell-user,\n.lens-cell-req { font-family: ui-monospace, monospace; font-size: 11.5px; }\n\n/* Auth lens action-cell color hints — green for success states\n   (authenticated/issued/exchanged/refreshed/validated), red for\n   rejection/failure family. Applied by `action-class` in lens/auth.cljs. */\n.lens-cell-op.ok  { color: var(--sy-success, #a8adb5); }\n.lens-cell-op.err { color: var(--sy-error,   #f7768e); }\n.lens-cell-op.ok  .lens-cell-drill { color: inherit; }\n.lens-cell-op.err .lens-cell-drill { color: inherit; }\n\n/* Topic chips — wire-schema-v2 `:topics` classification (the signal's\n   audience, orthogonal to level). Per-topic color via --topic-c so the\n   base chip is shared by the detail panel (.lens-topic-chip span) and the\n   stream rows (.lc-topic-chip button). */\n.lens-topics,\n.lc-row-topics { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 4px; }\n.lc-row-topics { margin-left: 8px; }\n\n.lens-topic-chip,\n.lc-topic-chip {\n  --topic-c: var(--sy-text-muted, #6b7280);\n  display: inline-block;\n  padding: 1px 6px;\n  font-family: ui-monospace, monospace;\n  font-size: 10px;\n  line-height: 1.5;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n  border-radius: 2px;\n  background: color-mix(in srgb, var(--topic-c) 14%, transparent);\n  color: var(--topic-c);\n  border: 1px solid color-mix(in srgb, var(--topic-c) 36%, transparent);\n}\n.lc-topic-chip { cursor: pointer; appearance: none; }\n.lc-topic-chip:hover { background: color-mix(in srgb, var(--topic-c) 26%, transparent); }\n\n/* ── Traffic lens — pure stats canvas. Generous padding + a consistent\n   gap between sections does the spacing work; individual sections don't\n   carry their own ad-hoc margins. ──────────────────────────────────────── */\n.lens-traffic {\n  padding: 16px 20px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n  overflow-y: auto;\n}\n\n/* ── Nav bar — ‹/› coarse paging + live jump. Fine navigation is\n   drag-pan + wheel-zoom on the canvas itself. ─────────────────────────── */\n.lens-range-bar {\n  display: flex; align-items: center; gap: 8px;\n}\n.lens-range-btn {\n  appearance: none; background: none; cursor: pointer;\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 40%, transparent);\n  border-radius: 4px; padding: 3px 10px;\n  font-size: 11px; color: var(--sy-text-muted, #6b7280);\n}\n.lens-range-btn:hover:not(:disabled) {\n  color: var(--sy-text, #e2e2e2); border-color: var(--sy-text-muted, #6b7280);\n}\n.lens-range-btn:disabled { opacity: .35; cursor: default; }\n.lens-range-window {\n  flex: 1; font-size: 11px; color: var(--sy-text-muted, #6b7280);\n  font-variant-numeric: tabular-nums; text-align: right;\n}\n.lens-range-live {\n  display: inline-flex; align-items: center; gap: 6px;\n}\n.lens-range-live.on {\n  color: var(--sy-ok, #6fae6f);\n  border-color: color-mix(in srgb, var(--sy-ok, #6fae6f) 60%, transparent);\n  background: color-mix(in srgb, var(--sy-ok, #6fae6f) 12%, transparent);\n}\n.lens-live-dot {\n  width: 7px; height: 7px; border-radius: 50%;\n  background: var(--sy-text-faint, #3a3a3a);\n}\n.lens-live-dot.on {\n  background: var(--sy-ok, #6fae6f);\n  box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-ok, #6fae6f) 70%, transparent);\n  animation: lens-live-pulse 1.6s ease-out infinite;\n}\n@keyframes lens-live-pulse {\n  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-ok, #6fae6f) 70%, transparent); }\n  70%  { box-shadow: 0 0 0 6px color-mix(in srgb, var(--sy-ok, #6fae6f) 0%, transparent); }\n  100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-ok, #6fae6f) 0%, transparent); }\n}\n\n/* ── Health verdict banner — is it OK right now ────────────────────────── */\n.lens-verdict {\n  display: flex; align-items: center; gap: 8px;\n  padding: 8px 14px; border-radius: 8px;\n  font-size: 12px;\n  border: 1px solid transparent;\n}\n.lens-verdict-dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }\n.lens-verdict-label {\n  font-weight: 600; text-transform: uppercase; letter-spacing: .05em;\n  font-size: 11px;\n}\n.lens-verdict-detail { color: var(--sy-text-muted, #6b7280); }\n.lens-verdict-rate {\n  margin-left: auto; font-variant-numeric: tabular-nums;\n  color: var(--sy-text, #e2e2e2); font-weight: 600;\n}\n.lens-verdict.healthy {\n  background: color-mix(in srgb, var(--sy-ok, #6fae6f) 10%, transparent);\n  border-color: color-mix(in srgb, var(--sy-ok, #6fae6f) 28%, transparent);\n}\n.lens-verdict.healthy  .lens-verdict-dot   { background: var(--sy-ok, #6fae6f); }\n.lens-verdict.healthy  .lens-verdict-label { color: var(--sy-ok, #6fae6f); }\n.lens-verdict.degraded {\n  background: color-mix(in srgb, var(--sy-warn, #e0af68) 12%, transparent);\n  border-color: color-mix(in srgb, var(--sy-warn, #e0af68) 34%, transparent);\n}\n.lens-verdict.degraded .lens-verdict-dot   { background: var(--sy-warn, #e0af68); }\n.lens-verdict.degraded .lens-verdict-label { color: var(--sy-warn, #e0af68); }\n.lens-verdict.critical {\n  background: color-mix(in srgb, var(--sy-error, #f0a0a0) 14%, transparent);\n  border-color: color-mix(in srgb, var(--sy-error, #f0a0a0) 40%, transparent);\n}\n.lens-verdict.critical .lens-verdict-dot   {\n  background: var(--sy-error, #f0a0a0);\n  box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-error, #f0a0a0) 70%, transparent);\n  animation: lens-crit-pulse 1.3s ease-out infinite;\n}\n.lens-verdict.critical .lens-verdict-label { color: var(--sy-error, #f0a0a0); }\n@keyframes lens-crit-pulse {\n  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-error, #f0a0a0) 70%, transparent); }\n  70%  { box-shadow: 0 0 0 7px color-mix(in srgb, var(--sy-error, #f0a0a0) 0%, transparent); }\n  100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--sy-error, #f0a0a0) 0%, transparent); }\n}\n.lens-verdict.idle {\n  background: color-mix(in srgb, var(--sy-text-muted, #6b7280) 8%, transparent);\n  border-color: color-mix(in srgb, var(--sy-text-muted, #6b7280) 22%, transparent);\n}\n.lens-verdict.idle .lens-verdict-dot   { background: var(--sy-text-muted, #6b7280); }\n.lens-verdict.idle .lens-verdict-label { color: var(--sy-text-muted, #6b7280); }\n\n/* ── Headline tiles ─────────────────────────────────────────────────── */\n.lens-stats-head {\n  display: flex; align-items: baseline; gap: 10px;\n  font-size: 11px; color: var(--sy-text-muted, #6b7280);\n}\n.lens-stats-title { text-transform: uppercase; letter-spacing: .06em; }\n.lens-stats-meta  { flex: 1; }\n.lens-stats-refresh {\n  appearance: none; background: none; cursor: pointer;\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 40%, transparent);\n  border-radius: 4px; padding: 3px 10px;\n  font-size: 11px; color: var(--sy-text-muted, #6b7280);\n}\n.lens-stats-refresh:hover { color: var(--sy-text, #e2e2e2); border-color: var(--sy-text-muted, #6b7280); }\n.lens-stats-tiles {\n  display: grid; gap: 12px;\n  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));\n}\n.lens-stat-tile {\n  appearance: none; text-align: left;\n  display: flex; flex-direction: column; gap: 3px;\n  padding: 12px 14px; border-radius: 8px;\n  background: color-mix(in srgb, var(--sy-text-muted, #6b7280) 8%, transparent);\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 20%, transparent);\n  color: inherit;\n}\n.lens-stat-tile.static { cursor: default; }\n.lens-stat-tile.err .lens-stat-value { color: var(--sy-error, #f0a0a0); }\n.lens-stat-value {\n  font-size: 19px; font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  color: var(--sy-text, #e2e2e2);\n}\n.lens-stat-label {\n  font-size: 10px; text-transform: uppercase; letter-spacing: .06em;\n  color: var(--sy-text-muted, #6b7280);\n}\n.lens-stat-sub { font-size: 10px; color: var(--sy-text-muted, #6b7280); }\n\n/* ── Traffic canvas card — pan/zoom time-series, the HERO ──────────────── */\n.lens-canvas-wrap {\n  position: relative;\n  user-select: none;\n  padding: 16px 18px 12px;\n  border-radius: 10px;\n  background: color-mix(in srgb, var(--sy-bg-surface, #1e1e1e) 55%, transparent);\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 18%, transparent);\n}\n.lens-canvas {\n  display: block; width: 100%; height: 220px; cursor: grab;\n  touch-action: none;\n}\n.lens-canvas:active { cursor: grabbing; }\n.lens-canvas-baseline {\n  stroke: color-mix(in srgb, var(--sy-text-muted, #6b7280) 50%, transparent);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n}\n.lens-canvas-tick {\n  stroke: color-mix(in srgb, var(--sy-text-muted, #6b7280) 16%, transparent);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n}\n.lens-canvas-crosshair {\n  stroke: var(--sy-text, #e2e2e2);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n  pointer-events: none;\n}\n.lens-canvas-bar {\n  fill: url(#traffic-ok);\n  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--sy-ok, #6fae6f) 45%, transparent));\n}\n.lens-canvas-bar.err {\n  fill: url(#traffic-err);\n  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--sy-error, #f0a0a0) 50%, transparent));\n}\n/* ── Live 'now' edge — a bright leading line; pulses while following ────── */\n.lens-canvas-now {\n  stroke: color-mix(in srgb, var(--sy-text, #e2e2e2) 40%, transparent);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n  stroke-dasharray: 3 3; pointer-events: none;\n}\n.lens-canvas-now.live {\n  stroke: var(--sy-ok, #6fae6f);\n  stroke-dasharray: none;\n}\n.lens-canvas-now-pulse {\n  fill: var(--sy-ok, #6fae6f);\n  transform-box: fill-box; transform-origin: center;\n  animation: lens-now-pulse 1.6s ease-out infinite;\n  pointer-events: none;\n}\n@keyframes lens-now-pulse {\n  0%   { opacity: .9; r: 3; }\n  70%  { opacity: 0;  r: 9; }\n  100% { opacity: 0;  r: 9; }\n}\n/* ── Health tint — the whole card takes on the verdict's mood ──────────── */\n.lens-canvas-wrap.verdict-degraded {\n  border-color: color-mix(in srgb, var(--sy-warn, #e0af68) 30%, transparent);\n  background: color-mix(in srgb, var(--sy-warn, #e0af68) 5%, color-mix(in srgb, var(--sy-bg-surface, #1e1e1e) 55%, transparent));\n}\n.lens-canvas-wrap.verdict-critical {\n  border-color: color-mix(in srgb, var(--sy-error, #f0a0a0) 38%, transparent);\n  background: color-mix(in srgb, var(--sy-error, #f0a0a0) 7%, color-mix(in srgb, var(--sy-bg-surface, #1e1e1e) 55%, transparent));\n}\n.lens-canvas-ticks { position: relative; height: 16px; margin-top: 4px; }\n.lens-canvas-tick-label {\n  position: absolute; top: 0; transform: translateX(-50%);\n  font-size: 10px; color: var(--sy-text-muted, #6b7280);\n  font-variant-numeric: tabular-nums; white-space: nowrap;\n}\n.lens-canvas-scale {\n  display: flex; justify-content: space-between;\n  font-size: 10px; font-variant-numeric: tabular-nums;\n  color: var(--sy-text-muted, #6b7280); margin-top: 4px;\n}\n.lens-canvas-scale .ok  { color: var(--sy-ok, #6fae6f); }\n.lens-canvas-scale .err { color: var(--sy-error, #f0a0a0); }\n\n/* ── Latency lane — p50/p95 over time, its OWN y-scale under the volume\n   chart (shared x-axis, not a dual-axis overlay) ──────────────────────── */\n.lens-latency-lane {\n  margin-top: 10px;\n  padding-top: 8px;\n  border-top: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 16%, transparent);\n}\n.lens-latency-label {\n  display: flex; justify-content: space-between; align-items: baseline;\n  font-size: 10px; text-transform: uppercase; letter-spacing: .05em;\n  color: var(--sy-text-muted, #6b7280); margin-bottom: 2px;\n}\n.lens-latency-peak { text-transform: none; letter-spacing: 0; font-variant-numeric: tabular-nums; }\n.lens-latency-svg { display: block; width: 100%; height: 64px; overflow: visible; }\n.lens-lat-p95 {\n  fill: none; stroke: var(--sy-warn, #e0af68); stroke-width: 1.5;\n  vector-effect: non-scaling-stroke; stroke-linejoin: round; stroke-linecap: round;\n}\n.lens-lat-p50 {\n  fill: none; stroke: color-mix(in srgb, var(--sy-warn, #e0af68) 55%, transparent);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n  stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 3 2;\n}\n.lens-canvas-hover-lat { color: var(--sy-warn, #e0af68); font-variant-numeric: tabular-nums; }\n\n/* ── Hover tooltip — minute + error rate under the cursor ──────────────── */\n.lens-canvas-hover {\n  position: absolute;\n  top: 10px;\n  transform: translateX(-50%);\n  z-index: 4;\n  pointer-events: none;\n  display: flex; flex-direction: column; gap: 2px;\n  padding: 6px 10px;\n  border-radius: 6px;\n  background: color-mix(in srgb, var(--sy-bg-app, #161616) 90%, transparent);\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 30%, transparent);\n  box-shadow: 0 4px 14px rgba(0,0,0,.35);\n  font-size: 11px; white-space: nowrap;\n}\n.lens-canvas-hover-time {\n  color: var(--sy-text, #e2e2e2); font-weight: 600;\n  font-variant-numeric: tabular-nums;\n}\n.lens-canvas-hover-row { display: flex; gap: 8px; font-variant-numeric: tabular-nums; }\n.lens-canvas-hover-row .ok  { color: var(--sy-ok, #6fae6f); }\n.lens-canvas-hover-row .err { color: var(--sy-error, #f0a0a0); }\n.lens-canvas-hover-rate { color: var(--sy-text-muted, #6b7280); }\n\n/* ── By-node breakdown card — which node serves the most traffic ───────── */\n.lens-by-node {\n  padding: 14px 16px 16px;\n  border-radius: 10px;\n  background: color-mix(in srgb, var(--sy-bg-surface, #1e1e1e) 55%, transparent);\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 18%, transparent);\n}\n.lens-by-node-title {\n  display: flex; align-items: baseline; gap: 8px;\n  font-size: 10px; text-transform: uppercase; letter-spacing: .06em;\n  color: var(--sy-text-muted, #6b7280); margin-bottom: 8px;\n}\n.lens-by-node-scope {\n  text-transform: none; letter-spacing: 0;\n  color: var(--sy-text-faint, #3a3a3a); font-size: 10px;\n}\n.lens-by-node-row {\n  display: grid; grid-template-columns: auto minmax(90px, 180px) 1fr auto;\n  align-items: center; gap: 10px;\n  padding: 6px 8px; border-radius: 6px;\n  font-size: 11.5px; font-variant-numeric: tabular-nums;\n  transition: background .12s ease;\n}\n.lens-by-node-row:hover {\n  background: color-mix(in srgb, var(--sy-text-muted, #6b7280) 8%, transparent);\n}\n.lens-by-node-dot {\n  width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0;\n  background: var(--node-c, var(--sy-accent, #e2e2e2));\n  box-shadow: 0 0 6px color-mix(in srgb, var(--node-c, var(--sy-accent, #e2e2e2)) 60%, transparent);\n}\n.lens-by-node-name {\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  font-family: ui-monospace, monospace;\n  color: var(--sy-text, #e2e2e2);\n}\n.lens-by-node-bar-wrap {\n  height: 6px; border-radius: 3px; overflow: hidden;\n  background: color-mix(in srgb, var(--sy-text-muted, #6b7280) 14%, transparent);\n}\n.lens-by-node-bar {\n  height: 100%; border-radius: 3px; min-width: 2px;\n  background: var(--sy-ok, #6fae6f);\n  transition: width .2s ease, background .2s ease;\n}\n/* Load bar coloured by ERROR RATE (matches the health verdict thresholds),\n   not a binary has-error flag. */\n.lens-by-node-bar.ok       { background: var(--sy-ok, #6fae6f); }\n.lens-by-node-bar.degraded { background: var(--sy-warn, #e0af68); }\n.lens-by-node-bar.critical { background: var(--sy-error, #f0a0a0); }\n.lens-by-node-count { color: var(--sy-text-muted, #6b7280); white-space: nowrap; }\n\n/* ── System lens time-window navigator — pan/zoom/brush timeline ───────── */\n.lens-timeline {\n  padding: 8px 12px 4px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  background: var(--sy-bg-surface, #1e1e1e);\n  flex-shrink: 0;\n  user-select: none;\n}\n.lens-tl-nav {\n  display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\n}\n.lens-tl-btn {\n  appearance: none; background: none; cursor: pointer;\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 40%, transparent);\n  border-radius: 4px; padding: 2px 9px;\n  font-size: 11px; color: var(--sy-text-muted, #6b7280);\n}\n.lens-tl-btn:hover { color: var(--sy-text, #e2e2e2); border-color: var(--sy-text-muted, #6b7280); }\n/* Draw the eye to \"⤒ latest\" when the current window has no rows — the\n   nudge to jump to where the data actually is. */\n.lens-tl-btn.nudge {\n  color: var(--sy-accent, #e2e2e2);\n  border-color: color-mix(in srgb, var(--sy-accent, #e2e2e2) 55%, transparent);\n  background: var(--sy-accent-tint, rgba(255,255,255,.10));\n}\n/* Preset zoom levels — equal-width so the group reads as an even segmented\n   control rather than ragged buttons. */\n.lens-tl-presets {\n  display: inline-flex; gap: 2px;\n  padding: 0 6px; margin: 0 2px;\n  border-left: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 22%, transparent);\n  border-right: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 22%, transparent);\n}\n.lens-tl-preset {\n  appearance: none; background: none; cursor: pointer;\n  border: 1px solid transparent; border-radius: 4px;\n  padding: 2px 0; min-width: 38px; text-align: center;\n  font-size: 11px;\n  color: var(--sy-text-muted, #6b7280); font-variant-numeric: tabular-nums;\n}\n.lens-tl-preset:hover { color: var(--sy-text, #e2e2e2); }\n.lens-tl-preset.on {\n  color: var(--sy-accent, #e2e2e2);\n  background: var(--sy-accent-tint, rgba(255,255,255,.14));\n}\n.lens-tl-span {\n  font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums;\n  color: var(--sy-accent, #e2e2e2);\n  min-width: 34px; text-align: center;\n}\n.lens-tl-label {\n  font-size: 11px; color: var(--sy-text-muted, #6b7280);\n  font-variant-numeric: tabular-nums; white-space: nowrap;\n}\n/* Pushes the row-count + live control to the right so the left cluster\n   stays tightly, evenly grouped. */\n.lens-tl-spacer { flex: 1 1 auto; }\n.lens-tl-count {\n  font-size: 10px; color: var(--sy-text-faint, #3a3a3a);\n  font-variant-numeric: tabular-nums; white-space: nowrap;\n}\n.lens-tl-count.capped { color: var(--sy-warn, #e0af68); }\n.lens-tl-live { display: inline-flex; align-items: center; gap: 6px; }\n.lens-tl-live.on {\n  color: var(--sy-ok, #6fae6f);\n  border-color: color-mix(in srgb, var(--sy-ok, #6fae6f) 60%, transparent);\n  background: color-mix(in srgb, var(--sy-ok, #6fae6f) 12%, transparent);\n}\n.lens-tl-live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--sy-text-faint, #3a3a3a); }\n.lens-tl-live-dot.on { background: var(--sy-ok, #6fae6f); animation: lens-live-pulse 1.6s ease-out infinite; }\n\n.lens-tl-strip-wrap { position: relative; }\n.lens-tl-strip {\n  display: block; width: 100%; height: 44px; cursor: grab;\n  touch-action: none;\n  background: color-mix(in srgb, var(--sy-bg-app, #161616) 60%, transparent);\n  border: 1px solid color-mix(in srgb, var(--sy-text-muted, #6b7280) 18%, transparent);\n  border-radius: 6px;\n}\n.lens-tl-strip:active { cursor: grabbing; }\n.lens-tl-tick {\n  stroke: color-mix(in srgb, var(--sy-text-muted, #6b7280) 18%, transparent);\n  stroke-width: 1; vector-effect: non-scaling-stroke;\n}\n/* Monochromatic density heatmap — one horizontal linearGradient (a stop\n   per bin) on a single rect: smooth in X, uniform in Y, neutral ink whose\n   opacity tracks the per-second rate on a constant scale. Fill + stops are\n   set in window_nav; no static fill needed here. */\n/* Edge grab-handles — drag to move that bound independently */\n.lens-tl-handle {\n  fill: color-mix(in srgb, var(--sy-accent, #e2e2e2) 14%, transparent);\n  cursor: ew-resize;\n}\n.lens-tl-handle:hover { fill: color-mix(in srgb, var(--sy-accent, #e2e2e2) 28%, transparent); }\n.lens-tl-grip {\n  stroke: color-mix(in srgb, var(--sy-accent, #e2e2e2) 55%, transparent);\n  stroke-width: 2; vector-effect: non-scaling-stroke; pointer-events: none;\n}\n/* Brush preview while resizing an edge (axis frozen) */\n.lens-tl-brush { fill: color-mix(in srgb, var(--sy-accent, #e2e2e2) 16%, transparent); }\n.lens-tl-brush-edge {\n  stroke: var(--sy-accent, #e2e2e2); stroke-width: 1.5;\n  vector-effect: non-scaling-stroke;\n}\n.lens-tl-ticks { position: relative; height: 14px; margin-top: 2px; }\n.lens-tl-tick-label {\n  position: absolute; top: 0; transform: translateX(-50%);\n  font-size: 10px; color: var(--sy-text-muted, #6b7280);\n  font-variant-numeric: tabular-nums; white-space: nowrap;\n}\n/* Edge ticks sit at left:0%/100% — centered transform would push half the\n   label past the strip's bounds (the end one goes fully invisible against\n   a clipping ancestor). Pin them inward instead. */\n.lens-tl-tick-label.edge-start { transform: translateX(0); }\n.lens-tl-tick-label.edge-end { transform: translateX(-100%); }\n\n.topic-system     { --topic-c: var(--sy-accent,    #e2e2e2); }\n.topic-dataset    { --topic-c: var(--sy-op-sql,     #a8adb5); }\n.topic-auth       { --topic-c: #d0d4da; }\n.topic-traffic    { --topic-c: var(--sy-text-muted, #6b7280); }\n.topic-audit      { --topic-c: var(--sy-op-write,   #f0f0f0); }\n.topic-diagnostic { --topic-c: #9aa0a8; }\n\n.lens-cell-shape,\n.lens-cell-pred {\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n  color: var(--sy-text-muted, #888);\n}\n\n.lens-cell-rows,\n.lens-cell-elapsed {\n  text-align: right;\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n  color: var(--sy-text-muted, #888);\n  width: 64px;\n}\n\n.lens-cell-drill {\n  background: transparent;\n  border: 0;\n  padding: 0;\n  margin: 0;\n  font: inherit;\n  color: var(--sy-text-primary, #d4d4d4);\n  cursor: pointer;\n  text-align: left;\n  border-bottom: 1px dotted transparent;\n  transition: border-color 60ms, color 60ms;\n}\n.lens-cell-drill:hover {\n  color: var(--sy-accent, #e2e2e2);\n  border-bottom-color: var(--sy-accent, #e2e2e2);\n}\n.lens-cell-empty { color: var(--sy-text-faint, #3a3a3a); }\n\n.lens-status {\n  display: inline-block;\n  padding: 1px 6px;\n  font-size: 10px;\n  text-transform: uppercase;\n  border-radius: 2px;\n}\n.lens-status.status-ok {\n  color: var(--sy-success, #a8adb5);\n  background: color-mix(in srgb, var(--sy-success, #a8adb5) 14%, transparent);\n}\n.lens-status.status-error {\n  color: var(--sy-error, #f7768e);\n  background: color-mix(in srgb, var(--sy-error, #f7768e) 14%, transparent);\n}\n\n/* ── Detail panel (expanded row) ─────────────────────────────────────────── */\n.lens-detail-row { background: var(--sy-bg-surface, #1e1e1e); }\n.lens-detail-cell {\n  padding: 12px 16px 16px 16px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n}\n.lens-detail {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 16px 24px;\n  font-family: ui-monospace, monospace;\n  font-size: 11.5px;\n}\n.lens-detail-section { min-width: 0; }\n.lens-detail-title {\n  font-family: 'Inter', system-ui, sans-serif;\n  font-size: 10.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--sy-text-faint, #3a3a3a);\n  margin-bottom: 6px;\n  padding-bottom: 4px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n}\n.lens-detail-kv {\n  display: grid;\n  grid-template-columns: 110px 1fr;\n  gap: 8px;\n  padding: 2px 0;\n  align-items: baseline;\n}\n.lens-detail-k {\n  color: var(--sy-text-muted, #888);\n}\n.lens-detail-v {\n  color: var(--sy-text-primary, #d4d4d4);\n  word-break: break-word;\n  white-space: pre-wrap;\n}\n/* Error spans the whole grid — traces are wide, and it lands below signal/data. */\n.lens-detail-error { grid-column: 1 / -1; }\n.lens-detail-error .lens-detail-title { color: var(--sy-error, #f7768e); }\n.lens-detail-hint {\n  font-family: 'Inter', system-ui, sans-serif;\n  font-size: 10.5px;\n  color: var(--sy-text-faint, #3a3a3a);\n  margin-top: 4px;\n  font-style: italic;\n}\n.lens-detail-audit-link .lens-detail-title { color: var(--sy-op-write, #f0f0f0); }\n.lens-audit-link {\n  display: inline-block;\n  height: 26px;\n  padding: 0 12px;\n  font-size: 12px;\n  background: transparent;\n  border: 1px dashed var(--sy-op-write, #f0f0f0);\n  border-radius: 3px;\n  color: var(--sy-op-write, #f0f0f0);\n  cursor: not-allowed;\n  opacity: 0.65;\n}\n.lens-detail-block {\n  grid-column: 1 / -1;        /* full-width row inside the grid */\n  min-width: 0;\n}\n.lens-detail-block-label {\n  font-family: 'Inter', system-ui, sans-serif;\n  font-size: 10.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--sy-text-faint, #3a3a3a);\n  margin-bottom: 4px;\n}\n.lens-detail-block-body {\n  margin: 0;\n  padding: 8px 10px;\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n  line-height: 1.55;\n  color: var(--sy-text-primary, #d4d4d4);\n  background: var(--sy-bg-app, #161616);\n  border-left: 2px solid var(--sy-accent, #e2e2e2);\n  border-radius: 2px;\n  overflow-x: auto;\n  white-space: pre;\n  max-height: 320px;\n  overflow-y: auto;\n}\n.lens-detail-trace {\n  margin-top: 6px;\n  padding: 8px 10px;\n  font-size: 10.5px;\n  line-height: 1.5;\n  color: var(--sy-text-muted, #888);\n  background: var(--sy-bg-app, #161616);\n  border-left: 2px solid var(--sy-error, #f7768e);\n  border-radius: 2px;\n  overflow-x: auto;\n  white-space: pre;\n}\n\n/* ── SQL trace section (nested under op-completed row, debug mode) ──────── */\n.lens-trace {\n  grid-column: 1 / -1;\n  min-width: 0;\n}\n.lens-trace .lens-detail-title { color: var(--sy-op-write, #f0f0f0); }\n.lens-trace-status {\n  font-family: ui-monospace, monospace;\n  font-size: 10.5px;\n  text-transform: none;\n  letter-spacing: 0;\n  color: var(--sy-text-muted, #888);\n}\n.lens-trace-table {\n  /* `table-layout: fixed` locks column widths to the THEAD definitions —\n   * without it, expanding a row with a long SQL string in the DATA cell\n   * causes neighbouring columns to shrink and the whole table reflows.\n   * Fixed layout keeps every other row at its original column widths. */\n  width: 100%;\n  table-layout: fixed;\n  margin-top: 6px;\n  border-collapse: collapse;\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n}\n.lens-trace-table colgroup col.lens-trace-col-time { width: 78px; }\n.lens-trace-table colgroup col.lens-trace-col-lvl  { width: 56px; }\n.lens-trace-table colgroup col.lens-trace-col-ns   { width: 120px; }\n.lens-trace-table colgroup col.lens-trace-col-id   { width: 180px; }\n.lens-trace-table colgroup col.lens-trace-col-msg  { width: 200px; }\n/* :col-data takes the rest */\n.lens-trace-table th {\n  text-align: left;\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--sy-text-faint, #3a3a3a);\n  padding: 4px 8px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n  background: var(--sy-bg-app, #161616);\n  font-weight: 500;\n}\n.lens-trace-row {\n  cursor: pointer;\n}\n.lens-trace-row td {\n  padding: 3px 8px;\n  vertical-align: top;\n  border-bottom: 1px solid color-mix(in srgb, var(--sy-border, #2a2a2a) 40%, transparent);\n  color: var(--sy-text-primary, #d4d4d4);\n}\n.lens-trace-row:hover { background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 6%, transparent); }\n.lens-trace-row.selected { background: color-mix(in srgb, var(--sy-accent, #e2e2e2) 12%, transparent); }\n.lens-trace-row.err {\n  background: color-mix(in srgb, var(--sy-error, #f7768e) 8%, transparent);\n  border-left: 2px solid var(--sy-error, #f7768e);\n}\n.lens-trace-row.err:hover { background: color-mix(in srgb, var(--sy-error, #f7768e) 14%, transparent); }\n.lens-trace-row.err.selected { background: color-mix(in srgb, var(--sy-error, #f7768e) 18%, transparent); }\n.lens-trace-ns {\n  color: var(--sy-text-muted, #888);\n  font-size: 10.5px;\n  white-space: nowrap;\n}\n.lens-trace-detail-row { background: var(--sy-bg-app, #161616); }\n.lens-trace-detail {\n  padding: 8px 14px 10px 14px;\n  border-bottom: 1px solid var(--sy-border, #2a2a2a);\n}\n.lens-trace-detail-block { margin-bottom: 6px; }\n.lens-trace-detail-block:last-child { margin-bottom: 0; }\n.lens-trace-detail-label {\n  font-family: 'Inter', system-ui, sans-serif;\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--sy-text-faint, #3a3a3a);\n  margin-bottom: 2px;\n}\n.lens-trace-detail-pre {\n  margin: 0;\n  padding: 6px 8px;\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n  line-height: 1.55;\n  color: var(--sy-text-primary, #d4d4d4);\n  background: var(--sy-bg-surface, #1e1e1e);\n  border-left: 2px solid var(--sy-accent, #e2e2e2);\n  border-radius: 2px;\n  /* Inner scroll: the detail row is bounded so expanding doesn't jolt the\n   * surrounding rows. Long SQL or stack traces scroll INSIDE this block. */\n  max-height: 180px;\n  overflow-x: auto;\n  overflow-y: auto;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n.lens-trace-detail-pre.lens-trace-detail-sql {\n  /* Wider scroll budget for the SQL block specifically — SQL strings often\n   * need horizontal room even after format-sql injects clause-breaks. */\n  max-height: 220px;\n  font-size: 11.5px;\n  border-left-color: var(--sy-op-write, #f0f0f0);\n}\n.lens-trace-ts {\n  color: var(--sy-text-muted, #888);\n  white-space: nowrap;\n}\n.lens-trace-lvl {\n  font-size: 10px;\n  text-transform: uppercase;\n  text-align: center;\n  width: 50px;\n}\n.lens-trace-lvl.lvl-trace { color: var(--sy-text-faint, #3a3a3a); }\n.lens-trace-lvl.lvl-debug { color: var(--sy-text-muted, #888); }\n.lens-trace-lvl.lvl-info  { color: var(--sy-info, #9aa0a8); }\n.lens-trace-lvl.lvl-warn  { color: var(--sy-warn, #e0af68); }\n.lens-trace-lvl.lvl-error,\n.lens-trace-lvl.lvl-fatal { color: var(--sy-error, #f7768e); }\n.lens-trace-id {\n  color: var(--sy-accent, #e2e2e2);\n  white-space: nowrap;\n}\n.lens-trace-msg { color: var(--sy-text-primary, #d4d4d4); }\n.lens-trace-data {\n  color: var(--sy-text-muted, #888);\n  font-size: 10.5px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.lens-trace-empty {\n  padding: 12px;\n  font-size: 11.5px;\n  color: var(--sy-text-faint, #3a3a3a);\n}\n.lens-trace-error { color: var(--sy-error, #f7768e); }\n\n/* ── Empty state ─────────────────────────────────────────────────────────── */\n.lens-empty {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  color: var(--sy-text-muted, #666);\n  font-size: 12px;\n  gap: 4px;\n}\n.lens-empty-title { font-size: 13px; color: var(--sy-text-primary, #d4d4d4); }\n.lens-empty-hint  { font-size: 11px; color: var(--sy-text-faint, #3a3a3a); }\n.lens-empty-msg   { color: var(--sy-error, #f7768e); }\n");
