function g$(a,b){a=N(a);var c=v(a,lk),d=Od(a,hG,UI),e=Od(a,KC,4),f=Od(a,rA,8);if(z.h(c,H7.g(Mo))){var h=tp.g(q(X));return new Ie(null,new R(null,2,5,S,[XJ,new k(null,3,[iK,["sy-popup-backdrop-",Vf(c)].join(""),FH,new k(null,3,[nB,"fixed",UC,"0",qM,"1200"],null),Lu,new k(null,1,[qn,function(m){m.stopPropagation();return f$()}],null)],null)],null),new Ie(null,new R(null,3,5,S,[XJ,new k(null,3,[iK,["sy-popup-",Vf(c)].join(""),FH,new k(null,6,[nB,"fixed",qM,"1201",YB,"0",HL,"scale(0.95)",Aba,"opacity 120ms ease-out, transform 120ms ease-out",
$n,"none"],null),oF,function(m){m=N(m);var n=v(m,eD);return requestAnimationFrame(function(){var r=UBa(h,new k(null,2,[BI,n.offsetWidth,fs,n.offsetHeight],null),function(){switch(d instanceof x?d.H:null){case "bottom-start":return new R(null,4,5,S,[UI,Hv,SM,xF],null);case "bottom":return new R(null,4,5,S,[yu,IC,UI,SM],null);case "bottom-end":return new R(null,4,5,S,[Hv,UI,xF,SM],null);case "top-start":return new R(null,4,5,S,[SM,xF,UI,Hv],null);case "top":return new R(null,4,5,S,[IC,yu,SM,UI],null);
case "top-end":return new R(null,4,5,S,[xF,SM,Hv,UI],null);default:return new R(null,4,5,S,[UI,Hv,SM,xF],null)}}(),e,f),t=N(r);r=v(t,ML);t=v(t,LL);n.style.left=[p.g(r),"px"].join("");n.style.top=[p.g(t),"px"].join("");n.style.opacity="1";n.style.transform="scale(1)";return n.style.pointerEvents="auto"})}],null),b],null),null,1,null),2,null)}return null};var y2=new CSSStyleSheet;y2.replaceSync('/* Entity Edit Drawer - floating right panel */\n\n.entity-drawer {\n  position: absolute;\n  top: 12px;\n  right: 12px;\n  bottom: 12px;\n  width: 520px;\n  max-width: calc(100% - 24px);\n  z-index: 1101;\n  display: flex;\n  flex-direction: column;\n  background: var(--modeling-overlay-bg);\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 12px;\n  box-shadow: var(--modeling-shadow-xl);\n  color: var(--sy-text);\n  overflow: hidden;\n}\n\n/* Header - blipkit style: title bar + name */\n.entity-drawer-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 16px 24px;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n}\n\n.entity-drawer-title {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 11px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--sy-text-m);\n}\n\n.entity-drawer-title .title-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  color: var(--sy-text-mm);\n  transition: color 0.2s;\n}\n\n.entity-drawer-title .title-icon:hover {\n  color: var(--sy-text-p);\n}\n\n.entity-drawer-actions {\n  display: flex;\n  gap: 16px;\n  align-items: center;\n}\n\n.entity-drawer-actions button {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 4px;\n  color: var(--sy-text-mm);\n  transition: color 0.15s;\n}\n\n.entity-drawer-actions button:hover {\n  color: var(--sy-text-pp);\n}\n\n.entity-drawer-actions button.action-danger:hover {\n  color: var(--modeling-removed-text);\n}\n\n/* Entity name below header */\n.entity-drawer-name {\n  font-size: 22px;\n  font-weight: 800;\n  color: var(--sy-text-pp);\n  border: none;\n  outline: none;\n  background: transparent;\n  padding: 16px 24px 12px;\n  width: 100%;\n  font-family: inherit;\n  line-height: 1.2;\n  box-sizing: border-box;\n}\n\n.entity-drawer-name::placeholder {\n  color: var(--sy-text-mm);\n}\n\n.entity-drawer-name.has-conflict {\n  color: var(--modeling-removed-text);\n}\n\n.entity-drawer-name-error {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 0 24px 8px;\n  font-size: 11.5px;\n  color: var(--modeling-removed-text);\n  flex-wrap: wrap;\n}\n\n.entity-drawer-name-error code {\n  padding: 1px 5px;\n  border-radius: 3px;\n  background: var(--modeling-removed-tint-strong);\n  color: var(--modeling-removed-text);\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 11px;\n}\n\n.entity-drawer-name-error strong {\n  font-weight: 600;\n}\n\n/* Tabs — HUD style: uppercase micro-labels over a hairline rail, the\n   active tab lit by a luminous beam (::after) that slides in on scaleX.\n   Hover previews a half-length dim beam. */\n.entity-drawer-tabs {\n  display: flex;\n  justify-content: space-between;\n  margin: 0 12px 12px;\n  border-bottom: 1px solid var(--sy-border-subtle);\n}\n\n.entity-drawer-tab {\n  position: relative;\n  padding: 6px 10px 10px;\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  cursor: pointer;\n  border: none;\n  background: transparent;\n  color: var(--sy-text-mm);\n  transition: color 0.18s;\n  white-space: nowrap;\n}\n\n.entity-drawer-tab::after {\n  content: "";\n  position: absolute;\n  left: 10px;\n  right: 10px;\n  bottom: -1px;\n  height: 2px;\n  border-radius: 1px;\n  background: var(--sy-accent);\n  transform: scaleX(0);\n  transform-origin: center;\n  opacity: 0;\n  transition: transform 0.22s ease, opacity 0.22s ease;\n}\n\n.entity-drawer-tab:hover {\n  color: var(--sy-text);\n}\n\n.entity-drawer-tab:hover::after {\n  transform: scaleX(0.45);\n  opacity: 0.45;\n}\n\n.entity-drawer-tab.active {\n  color: var(--sy-text-pp);\n}\n\n.entity-drawer-tab.active::after {\n  transform: scaleX(1);\n  opacity: 1;\n  box-shadow: 0 0 8px var(--sy-accent-border);\n}\n\n/* Tab content area */\n.entity-drawer-content {\n  flex: 1;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  padding: 0 24px 24px;\n}\n\n/* Attributes tab: tight 2px horizontal padding so the grid uses max width */\n.entity-drawer-content.tab-attributes {\n  padding: 0 2px 24px;\n}\n\n/* Attribute rows - blipkit compact style */\n.attr-row {\n  display: grid;\n  grid-template-columns: 20px 100px 1fr 100px 20px 24px;\n  gap: 0;\n  height: 28px;\n  font-size: 11px;\n  color: var(--sy-text);\n  align-items: center;\n  border: none;\n}\n\n/* Attr group wraps row + enum expansion */\n.attr-group {\n  position: relative;\n}\n\n.attr-row[draggable] {\n  cursor: grab;\n}\n\n.attr-row:hover {\n  background: var(--modeling-overlay-bg-hover);\n  border-radius: 2px;\n}\n\n.attr-row.attr-dragging {\n  opacity: 0.3;\n}\n\n.attr-row.attr-drag-over {\n  border-top: 2px solid var(--sy-accent);\n  margin-top: -2px;\n}\n\n.attr-row:focus-within {\n  background: var(--modeling-overlay-bg-hover);\n  border-radius: 2px;\n}\n\n.attr-header {\n  height: 28px;\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--sy-text-m);\n  border-bottom: none;\n}\n\n.attr-header:hover {\n  background: none;\n  margin: 0;\n  padding: 0;\n}\n\n.attr-constraint {\n  font-size: 11px;\n  color: var(--sy-text-p);\n}\n\n/* unique+mandatory (natural key) — same # glyph as unique, key-tinted */\n.constraint-natural-key {\n  color: var(--sy-key);\n}\n\n.attr-row:hover .attr-name {\n  color: var(--sy-text-pp);\n}\n\n.attr-name {\n  font-weight: 500;\n  font-size: 11px;\n  color: var(--sy-text-p);\n}\n\n.attr-type {\n  font-size: 11px;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--sy-text-p);\n}\n\n.attr-delete {\n  background: none;\n  border: none;\n  cursor: pointer;\n  opacity: 0;\n  color: var(--sy-text-m);\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: opacity 0.2s ease-in-out;\n}\n\n.attr-row:hover .attr-delete {\n  opacity: 0.5;\n}\n\n.attr-delete:hover {\n  opacity: 1 !important;\n  color: var(--modeling-removed-text);\n}\n\n/* Attribute guard — deny-list toggle (see guard-cell). Hover-reveal like\n   .attr-delete when unguarded; stays visible + tinted once a role is\n   actually denied so guarded attributes are scannable at a glance. */\n.attr-guard {\n  background: none;\n  border: none;\n  cursor: pointer;\n  opacity: 0;\n  color: var(--sy-text-m);\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: opacity 0.2s ease-in-out;\n}\n\n.attr-row:hover .attr-guard {\n  opacity: 0.5;\n}\n\n.attr-guard:hover {\n  opacity: 1 !important;\n}\n\n.attr-guard.active {\n  opacity: 1;\n  color: var(--sy-warn, #b7791f);\n}\n\n.attr-guard:disabled {\n  cursor: not-allowed;\n}\n\n.attr-row:hover .attr-guard:disabled {\n  opacity: 0.2;\n}\n\n/* Attribute access-policy modal — reuses .guard-modal chrome (backdrop,\n   header, search, footer) from the RLS path selector; only the Role x\n   {Read, Write} grid below is specific. Narrower than the path selector:\n   three columns, not path visualizations. */\n.attr-policy-modal {\n  width: 460px;\n}\n\n/* Shared grid so the fixed header lines up with the scrolling rows */\n.attr-policy-head,\n.attr-policy-row {\n  display: grid;\n  grid-template-columns: 1fr 56px 56px;\n  align-items: center;\n  gap: 0;\n}\n\n.attr-policy-head {\n  padding: 0 24px 6px;\n  font-size: 10px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--sy-text-m);\n}\n\n.attr-policy-head span:not(:first-child) {\n  text-align: center;\n}\n\n/* Constant height (~6 rows) so the modal doesn\'t resize as you filter */\n.attr-policy-list {\n  overflow-y: auto;\n  padding: 0 24px 16px;\n  height: 240px;\n  flex: none;\n}\n\n.attr-policy-row {\n  height: 34px;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n}\n\n.attr-policy-row:last-child {\n  border-bottom: none;\n}\n\n.attr-policy-role {\n  font-size: 12px;\n  color: var(--sy-text-p);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.attr-policy-cell {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n}\n\n.attr-policy-hint {\n  font-size: 11px;\n  color: var(--sy-text-mm);\n}\n\n/* Classification — metadata, not enforcement. Fixed strip above the\n   access grid; tags that also drive audit redaction are marked. */\n.attr-class-section {\n  padding: 0 24px 12px;\n}\n\n.attr-class-label {\n  font-size: 10px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--sy-text-m);\n  padding-bottom: 6px;\n}\n\n.attr-class-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.attr-class-chip {\n  padding: 4px 10px;\n  border-radius: 999px;\n  border: 1px solid var(--modeling-overlay-border);\n  background: transparent;\n  color: var(--sy-text-m);\n  font-size: 11px;\n  font-family: inherit;\n  cursor: pointer;\n  transition:\n    border-color 0.15s,\n    color 0.15s,\n    background 0.15s;\n}\n\n.attr-class-chip:hover {\n  border-color: var(--sy-text-mm);\n  color: var(--sy-text);\n}\n\n.attr-class-chip.on {\n  border-color: var(--sy-accent);\n  color: var(--sy-text-pp);\n  background: var(--sy-accent-tint);\n}\n\n/* Tags that withhold values from the audit trail read as a warning, not\n   a neutral selection — the consequence is data NOT being recorded. */\n.attr-class-chip.on.redacting {\n  border-color: var(--sy-warn, #b7791f);\n  color: var(--sy-warn, #b7791f);\n  background: color-mix(in srgb, var(--sy-warn, #b7791f) 12%, transparent);\n}\n\n.attr-class-hint {\n  font-size: 11px;\n  color: var(--sy-text-mm);\n  padding-top: 8px;\n  line-height: 1.4;\n}\n\n/* Row indicator — a classified attribute is scannable without opening\n   the modal, same idea as the amber guard shield. */\n.attr-class-dot {\n  width: 5px;\n  height: 5px;\n  border-radius: 50%;\n  background: var(--sy-warn, #b7791f);\n  margin-left: 4px;\n  flex-shrink: 0;\n}\n\n/* Enum chevron */\n.enum-chevron {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  color: var(--sy-text-m);\n  transition:\n    transform 0.25s ease-in-out,\n    color 0.15s;\n  transform: rotate(0deg);\n}\n\n.enum-chevron:hover {\n  color: var(--sy-text-pp);\n}\n\n.enum-chevron.expanded {\n  transform: rotate(90deg);\n}\n\n/* Enum values list — animated wrapper */\n.enum-wrapper {\n  height: 0;\n  overflow: hidden;\n  transition: height 0.25s ease-in-out;\n}\n\n.enum-inner {\n  padding: 8px 24px 8px 20px;\n}\n\n.enum-box {\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  padding: 6px 8px;\n}\n\n.enum-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  height: 28px;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sy-text-p);\n}\n\n.enum-toggle {\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  color: var(--sy-text-mm);\n  transition: color 0.15s;\n}\n\n.enum-toggle.active {\n  color: var(--sy-accent);\n}\n\n.enum-name {\n  flex: 1;\n  background: transparent;\n  border: none;\n  outline: none;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sy-text-p);\n  font-family: inherit;\n  padding: 0;\n  user-select: none;\n}\n\n.enum-row.inactive .enum-name {\n  color: var(--sy-text-mm);\n}\n\n.enum-name::placeholder {\n  color: var(--sy-text-mm);\n  font-weight: 400;\n}\n\n.enum-delete {\n  cursor: pointer;\n  opacity: 0;\n  color: var(--sy-text-m);\n  display: flex;\n  align-items: center;\n  transition: opacity 0.2s;\n}\n\n.enum-row:hover .enum-delete {\n  opacity: 0.5;\n}\n\n.enum-delete:hover {\n  opacity: 1 !important;\n  color: var(--modeling-removed-text);\n}\n\n/* Constraints tab: empty state when no attributes are marked unique */\n.constraints-empty {\n  margin-top: 8px;\n  padding: 16px;\n  border: 1px dashed var(--modeling-overlay-border);\n  border-radius: 6px;\n  text-align: center;\n}\n\n.constraints-empty-title {\n  margin: 0 0 6px;\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--sy-text-p);\n}\n\n.constraints-empty-hint {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--sy-text-mm);\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Constraint Groups (unique constraint DnD)\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n.constraint-groups {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding-top: 8px;\n}\n\n.constraint-group {\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  padding: 10px;\n  min-height: 44px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  align-items: center;\n  transition:\n    border-color 0.15s,\n    background 0.15s;\n}\n\n.constraint-group.empty {\n  border-style: dashed;\n  justify-content: center;\n}\n\n.constraint-group.drag-over {\n  border-color: var(--sy-accent);\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.constraint-group.drag-over .constraint-empty {\n  display: none;\n}\n\n.constraint-empty {\n  font-size: 11px;\n  color: var(--sy-text-mm);\n  user-select: none;\n  pointer-events: none;\n}\n\n.constraint-chip {\n  background: var(--modeling-overlay-bg-hover);\n  border: 1px solid var(--modeling-overlay-border);\n  padding: 4px 10px;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sy-text-p);\n  cursor: grab;\n  user-select: none;\n  transition:\n    opacity 0.15s,\n    box-shadow 0.15s;\n}\n\n.constraint-chip:hover {\n  box-shadow: var(--modeling-shadow-md);\n}\n\n.constraint-chip.dragging {\n  opacity: 0.3;\n}\n\n/* During drag, chips in target group shouldn\'t steal events */\n.constraint-group.drag-over .constraint-chip {\n  pointer-events: none;\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Toggle Switch\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n.sy-toggle {\n  position: relative;\n  width: 40px;\n  height: 22px;\n  min-width: 40px;\n  border-radius: 12px;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n  background: var(--modeling-overlay-border);\n  transition: background 0.2s;\n  flex-shrink: 0;\n}\n\n.sy-toggle.active {\n  background: var(--sy-accent);\n}\n\n.sy-toggle-thumb {\n  position: absolute;\n  top: 3px;\n  left: 3px;\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  background: var(--modeling-button-text);\n  box-shadow: var(--modeling-shadow-sm);\n  transition: left 0.2s;\n  pointer-events: none;\n}\n\n.sy-toggle.active .sy-toggle-thumb {\n  left: 20px;\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Guard Tab\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n.guard-card {\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  padding: 16px;\n  margin: 8px 0 12px;\n}\n\n.guard-card-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.guard-status {\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--sy-text-m);\n}\n\n.guard-status.active {\n  color: var(--sy-accent);\n}\n\n.guard-description {\n  font-size: 12px;\n  line-height: 1.6;\n  color: var(--sy-text-m);\n  margin: 10px 0 0;\n}\n\n/* Guard rows container */\n.guard-rows {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding-top: 4px;\n}\n\n/* Individual guard row */\n.guard-row {\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  transition: border-color 0.15s;\n}\n\n.guard-row:hover {\n  border-color: var(--sy-text-mm);\n}\n\n/* Guard row header: edit + ops + delete */\n.guard-row-header {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n}\n\n.guard-row-spacer {\n  flex: 1;\n}\n\n.guard-edit-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 4px;\n  color: var(--sy-text-mm);\n  border-radius: 4px;\n  transition: color 0.15s;\n}\n\n.guard-edit-btn:hover {\n  color: var(--sy-text);\n}\n\n/* Operation pill */\n.guard-op {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 3px 8px;\n  border-radius: 4px;\n  font-size: 11px;\n  font-weight: 600;\n  cursor: pointer;\n  color: var(--sy-text-mm);\n  background: transparent;\n  border: 1px solid var(--modeling-overlay-border);\n  transition: all 0.15s;\n  user-select: none;\n}\n\n.guard-op:hover {\n  border-color: var(--sy-text-m);\n  color: var(--sy-text);\n}\n\n.guard-op.active {\n  background: var(--sy-accent);\n  border-color: var(--sy-accent);\n  color: var(--modeling-button-text);\n}\n\n/* Guard delete button */\n.guard-delete {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 4px;\n  color: var(--sy-text-mm);\n  opacity: 0;\n  transition:\n    opacity 0.15s,\n    color 0.15s;\n}\n\n.guard-row:hover .guard-delete {\n  opacity: 0.6;\n}\n\n.guard-delete:hover {\n  opacity: 1 !important;\n  color: var(--modeling-removed-text);\n}\n\n/* Guard row paths area */\n.guard-row-paths {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 10px 12px;\n}\n\n/* Path display wrapper */\n.guard-path-display {\n  padding: 6px 8px;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 4px;\n}\n\n/* AND/OR separators */\n.guard-and-separator {\n  display: flex;\n  justify-content: center;\n  padding: 2px 0;\n}\n\n.guard-and-separator span {\n  font-size: 10px;\n  font-weight: 700;\n  text-transform: uppercase;\n  color: var(--sy-accent);\n}\n\n.guard-or-separator {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 6px 0;\n}\n\n.guard-or-line {\n  flex: 1;\n  height: 1px;\n  background: var(--modeling-overlay-border);\n}\n\n.guard-or-text {\n  font-size: 11px;\n  font-weight: 700;\n  text-transform: uppercase;\n  color: var(--sy-accent);\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Path Visual Components\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n\n/* Path content: horizontal flow of steps + arrows */\n.guard-path-content {\n  display: flex;\n  align-items: flex-end;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n\n.guard-path-steps-group {\n  display: flex;\n  align-items: flex-end;\n  gap: 6px;\n}\n\n/* Path step: relation label on top, entity chip below */\n.guard-path-step {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 2px;\n}\n\n.guard-path-step-label {\n  font-size: 10px;\n  color: var(--sy-text-mm);\n  font-style: italic;\n  text-align: center;\n  white-space: nowrap;\n}\n\n.guard-path-step-chip {\n  padding: 3px 8px;\n  border-radius: 4px;\n  background: var(--modeling-overlay-bg-hover);\n  border: 1px solid var(--modeling-overlay-border);\n  color: var(--sy-text-p);\n  font-size: 11px;\n  font-weight: 500;\n  text-align: center;\n  white-space: nowrap;\n}\n\n.guard-path-step-chip.ref {\n  border-color: var(--sy-accent);\n}\n\n/* Arrow between steps */\n.guard-path-arrow {\n  display: flex;\n  align-items: flex-end;\n  padding-bottom: 4px;\n  color: var(--sy-text-mm);\n  font-size: 13px;\n}\n\n/* Target icon (user/group/role) */\n.guard-target-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 22px;\n  height: 22px;\n  margin-left: auto;\n  color: var(--sy-accent);\n}\n\n/* Path ID label */\n.guard-path-id {\n  font-size: 10px;\n  font-weight: 700;\n  color: var(--sy-text-mm);\n  min-width: 16px;\n  text-align: center;\n  padding-bottom: 4px;\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Path Selector Modal\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n\n/* Modal backdrop - covers entire modeling area */\n.guard-modal-backdrop {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 2000;\n  background: var(--modeling-modal-backdrop);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n/* Modal dialog */\n.guard-modal {\n  width: 620px;\n  max-width: calc(100vw - 48px);\n  max-height: calc(100vh - 80px);\n  background: var(--modeling-overlay-bg);\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 12px;\n  box-shadow: var(--modeling-shadow-modal);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.guard-modal-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 20px 24px 16px;\n  font-size: 18px;\n  font-weight: 600;\n  color: var(--sy-text-pp);\n}\n\n.guard-modal-close {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  color: var(--sy-text-mm);\n  padding: 4px;\n  border-radius: 4px;\n  transition: color 0.15s;\n}\n\n.guard-modal-close:hover {\n  color: var(--sy-text);\n}\n\n.guard-modal-search {\n  padding: 0 24px 12px;\n}\n\n.guard-modal-search input {\n  width: 100%;\n  padding: 10px 14px;\n  border-radius: 6px;\n  border: 1px solid var(--modeling-overlay-border);\n  background: transparent;\n  color: var(--sy-text);\n  font-size: 14px;\n  font-family: inherit;\n  outline: none;\n  box-sizing: border-box;\n}\n\n.guard-modal-search input:focus {\n  border-color: var(--sy-accent);\n}\n\n.guard-modal-count {\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  color: var(--sy-accent);\n  padding: 0 24px 8px;\n  min-height: 14px; /* always occupies one line — no layout jump on select */\n}\n\n.guard-modal-count.none {\n  color: var(--sy-text-mm);\n  font-weight: 400;\n  font-style: italic;\n  text-transform: none;\n}\n\n/* Scrollable path list — CONSTANT height (~5 items) regardless of option\n   count, with breathing room at the bottom of the scroll run. */\n.guard-modal-list {\n  overflow-y: auto;\n  padding: 0 24px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  /* 5 × item (2px borders + 10px padding ×2 + ~44px content) + 4 gaps */\n  height: 364px;\n  flex: none;\n}\n\n/* Selectable path item in modal */\n.guard-modal-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 12px;\n  border: 2px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  cursor: pointer;\n  transition:\n    border-color 0.15s,\n    background 0.15s;\n}\n\n.guard-modal-item:hover {\n  border-color: var(--sy-text-mm);\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.guard-modal-item.selected {\n  border-color: var(--sy-accent);\n}\n\n/* Selection check circle */\n.guard-selector-check {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 20px;\n  height: 20px;\n  min-width: 20px;\n  border-radius: 50%;\n  border: 2px solid var(--modeling-overlay-border);\n  color: transparent;\n  transition: all 0.15s;\n  flex-shrink: 0;\n}\n\n.guard-selector-check.active {\n  background: var(--sy-accent);\n  border-color: var(--sy-accent);\n  color: var(--modeling-button-text);\n}\n\n/* Modal footer */\n.guard-modal-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 16px 24px;\n  border-top: 1px solid var(--modeling-overlay-border);\n}\n\n.guard-modal-warnings {\n  flex: 1;\n  min-height: 15px; /* reserve the warning line — footer never jumps */\n}\n\n.guard-selector-warning {\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--modeling-removed-text);\n}\n\n.guard-modal-buttons {\n  display: flex;\n  gap: 8px;\n  margin-left: 16px;\n}\n\n.guard-modal-cancel,\n.guard-modal-save {\n  padding: 8px 20px;\n  border-radius: 6px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  border: 1px solid var(--modeling-overlay-border);\n  background: transparent;\n  color: var(--sy-text);\n  transition: all 0.15s;\n}\n\n.guard-modal-cancel:hover {\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.guard-modal-save {\n  background: var(--sy-accent);\n  border-color: var(--sy-accent);\n  color: var(--modeling-button-text);\n}\n\n.guard-modal-save:hover {\n  opacity: 0.9;\n}\n\n.guard-modal-save.disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n/* No paths message */\n.guard-no-paths {\n  font-size: 12px;\n  color: var(--sy-text-mm);\n  padding: 12px 0;\n  text-align: center;\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Access Tab\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n.access-section {\n  margin-bottom: 20px;\n  padding-top: 8px;\n}\n\n.access-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.access-label {\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--sy-text-p);\n}\n\n.audit-option {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  cursor: pointer;\n}\n\n.audit-option span {\n  color: var(--sy-text-mm);\n  transition: color 0.15s;\n}\n\n.audit-option.active span {\n  color: var(--sy-text);\n}\n\n/* Access tab: scoped scroll — tab body stays fixed, matrix scrolls */\n.entity-drawer-content.tab-access {\n  overflow: hidden;\n}\n\n.access-tab-body {\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n  min-height: 0;\n}\n\n/* Role filter input */\n.access-filter {\n  margin-bottom: 8px;\n}\n\n.access-filter input {\n  width: 100%;\n  padding: 8px 12px;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  background: transparent;\n  color: var(--sy-text);\n  font-size: 13px;\n  font-family: inherit;\n  outline: none;\n  box-sizing: border-box;\n  transition: border-color 0.15s;\n}\n\n.access-filter input:focus {\n  border-color: var(--sy-accent);\n}\n\n.access-filter input::placeholder {\n  color: var(--sy-text-mm);\n}\n\n/* Header + scroll wrapper — the header sits OUTSIDE the scrolling area (its\n   own fixed row) rather than `position: sticky` inside it. Sticky-in-overflow\n   made the header\'s own right-edge padding (for the scrollbar gutter, below)\n   piggyback on the scroll container\'s box model, which is fragile; a plain\n   non-scrolling header row sidesteps that entirely. This box owns the border\n   + rounded corners for the whole table; .access-scroll below is just the\n   clipped, scrolling body. */\n.access-table {\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n  min-height: 0;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  overflow: hidden;\n}\n\n.access-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n}\n\n/* Role access matrix */\n.access-matrix {\n  display: flex;\n  flex-direction: column;\n}\n\n/* Flex, not grid — a fixed grid-template-columns can\'t adapt to the actual\n   op count (6 for entities since CRUDOB, 3 for relations); flex anchors\n   whatever .access-col\n   slots are present flush to the right, with .access-role-name eating the\n   rest. Each row (not the scroll wrapper) carries its own right padding, so\n   the columns clear the scrollbar gutter regardless of what wraps them. */\n.access-matrix-header,\n.access-matrix-row {\n  display: flex;\n  align-items: center;\n  padding-right: 8px;\n}\n\n.access-matrix-header {\n  flex: none;\n  background: var(--sy-bg-band);\n  border-bottom: 1px solid var(--modeling-overlay-border);\n  font-size: 10px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--sy-text-mm);\n}\n\n.access-matrix-row {\n  border-bottom: 1px solid var(--modeling-overlay-border);\n  transition: background 0.15s;\n}\n\n.access-matrix-row:last-child {\n  border-bottom: none;\n}\n\n.access-matrix-row:hover {\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.access-role-name {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 8px 12px;\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sy-text-p);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.access-matrix-header .access-role-name {\n  font-size: 10px;\n  font-weight: 700;\n  color: var(--sy-text-mm);\n}\n\n/* Fixed-width column slot — anchors headers and row cells to the same\n   36px track regardless of how many op columns the drawer defines. */\n.access-col {\n  flex: 0 0 36px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.access-col-header {\n  padding: 8px 0;\n  cursor: default;\n}\n\n.access-cell {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 4px;\n  background: transparent;\n  color: transparent;\n  cursor: pointer;\n  transition: all 0.15s;\n  padding: 0;\n}\n\n.access-cell:hover {\n  border-color: var(--sy-text-mm);\n}\n\n.access-cell.granted {\n  background: var(--sy-accent);\n  border-color: var(--sy-accent);\n  color: var(--modeling-button-text);\n}\n\n/* Implied, not held: O grants every op, B grants read — the cell is already\n   effectively on, so show it lit but hollow (dashed, tinted) to distinguish\n   "you granted this" from "this comes for free". Still clickable: clicking\n   adds the explicit grant, which is a no-op access-wise but harmless. */\n.access-cell.implied {\n  background: var(--sy-accent-soft, transparent);\n  border-style: dashed;\n  border-color: var(--sy-accent-border, var(--sy-accent));\n  color: var(--sy-accent);\n  opacity: 0.65;\n}\n\n.access-cell.granted:hover {\n  opacity: 0.85;\n}\n\n.access-empty,\n.access-deploy-gate {\n  font-size: 12px;\n  color: var(--sy-text-mm);\n  padding: 12px;\n  text-align: center;\n  border: 1px dashed var(--modeling-overlay-border);\n  border-radius: 6px;\n}\n\n/* Add action - ghost button */\n.add-action {\n  font-size: 11px;\n  font-weight: 600;\n  cursor: pointer;\n  background: transparent;\n  border: none;\n  padding: 4px 0;\n  color: var(--sy-text-m);\n  transition: color 0.15s;\n}\n\n.add-action:hover {\n  color: var(--sy-text-p);\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Attribute name conflict / reactivation hints\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n.attr-row.attr-has-conflict .attr-name {\n  color: var(--modeling-removed-text);\n}\n\n.attr-conflict-error {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 4px;\n  margin: 2px 0 6px 28px;\n  font-size: 11px;\n  color: var(--modeling-removed-text);\n}\n\n.attr-conflict-error code {\n  padding: 0 4px;\n  border-radius: 3px;\n  background: var(--modeling-removed-tint-strong);\n  color: var(--modeling-removed-text);\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 10.5px;\n}\n\n.attr-reactivate-hint {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 4px;\n  margin: 2px 0 6px 28px;\n  font-size: 11px;\n  color: var(--sy-text-m);\n}\n\n.attr-reactivate-hint strong {\n  font-weight: 600;\n  color: var(--sy-text);\n}\n\n.attr-reactivate-btn {\n  margin-left: 4px;\n  padding: 2px 8px;\n  border: 1px solid var(--sy-accent);\n  border-radius: 4px;\n  background: transparent;\n  color: var(--sy-accent);\n  font-size: 10.5px;\n  font-weight: 500;\n  font-family: inherit;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.attr-reactivate-btn:hover {\n  background: var(--modeling-entity-selected-header);\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Configuration rot — broken rule diagnostics\n   A quiet-but-unmistakable hazard surface: gutter\n   accent + faint diagonal hazard stripes, ghost\n   chip for the dead reference, verdict note.\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n\n@keyframes rot-reveal {\n  from { opacity: 0; transform: translateY(-2px); }\n  to   { opacity: 1; transform: none; }\n}\n\n.guard-rot {\n  position: relative;\n  padding: 7px 10px 8px 12px;\n  border: 1px solid var(--modeling-rot-border);\n  border-left: 3px solid var(--modeling-rot-text);\n  border-radius: 4px;\n  background:\n    repeating-linear-gradient(\n      -45deg,\n      transparent 0 7px,\n      color-mix(in srgb, var(--modeling-rot-text) 4%, transparent) 7px 8px),\n    var(--modeling-rot-fill);\n  animation: rot-reveal 160ms ease-out;\n}\n\n/* header: icon · title · kind ─────────── remove */\n.guard-rot-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.guard-rot-icon {\n  display: flex;\n  align-items: center;\n  color: var(--modeling-rot-text);\n  flex: none;\n}\n\n.guard-rot-title {\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--modeling-rot-text);\n  white-space: nowrap;\n}\n\n.guard-rot-kind {\n  font-size: 10px;\n  font-style: italic;\n  color: var(--sy-text-m);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.guard-rot-remove {\n  margin-left: auto;\n  flex: none;\n  padding: 2px 9px;\n  border: 1px solid var(--modeling-rot-border);\n  border-radius: 3px;\n  background: transparent;\n  color: var(--modeling-rot-text);\n  font-size: 10px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  cursor: pointer;\n  transition: background 120ms ease, color 120ms ease, border-color 120ms ease;\n}\n\n.guard-rot-remove:hover {\n  background: var(--modeling-rot-text);\n  border-color: var(--modeling-rot-text);\n  color: var(--modeling-rot-fill);\n}\n\n/* body: the dead reference, rendered as a ghost chip */\n.guard-rot-body {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin-top: 6px;\n  flex-wrap: wrap;\n}\n\n.guard-rot-ghost {\n  padding: 2px 8px;\n  border: 1px dashed var(--modeling-rot-border);\n  border-radius: 4px;\n  background: color-mix(in srgb, var(--modeling-rot-text) 6%, transparent);\n  color: var(--modeling-rot-text);\n  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;\n  font-size: 10px;\n  letter-spacing: 0.01em;\n  opacity: 0.85;\n}\n\n.guard-rot-ghost-label {\n  font-size: 10px;\n  font-style: italic;\n  color: var(--sy-text-m);\n}\n\n/* verdict note */\n.guard-rot-note {\n  margin: 6px 0 0;\n  font-size: 10px;\n  line-height: 1.45;\n  color: var(--sy-text-m);\n}\n\n.guard-rot-note strong {\n  color: var(--modeling-rot-text);\n  font-weight: 600;\n}\n\n/* constraints-tab variant: banner spacing above the groups */\n.constraint-rot {\n  margin-bottom: 10px;\n}\n\n.constraint-rot-groups {\n  gap: 6px;\n}\n');
